(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["sl"] = {"ui":{"skip":"Preskoči na vsebino","back":"← Nazaj na AI-gile","lang.button":"Jezik: {name}","lang.dialog":"Izberi jezik","lang.search":"Išči jezike","lang.none":"Noben jezik se ne ujema","lang.notYet":"{name} še ni preveden","theme.aria":"Preklopi temo: svetla, temna ali črna","theme.toLight":"Preklopi na svetlo temo","theme.toDark":"Preklopi na temno temo","theme.toBlack":"Preklopi na črno temo (prava črna, prijazna do zaslonov OLED)","words.underline":"Podčrtaj te besede na strani","words.underlineHelp":"Postavi miško nad pikčasto podčrtano besedo ali se je dotakni, da vidiš, kaj pomeni.","index.title":"AI-gile: tvoja AI razvojna ekipa na eni tabli","index.description":"AI-gile je kanban tabla za ekipe AI programerjev. Delajo, medtem ko spiš; ti dobiš eno kratko skupino reči, o katerih odločiš, jih preizkusiš in sprejmeš.","hero.logoAlt":"Ikona table AI-gile","hero.h1.html":"Tvoja AI razvojna ekipa na eni&nbsp;tabli.","hero.alpha":"🐣 Zaprta pred-alfa","hero.alphaTitle":"Zgodnja in nedokončana različica: hvala, da jo preizkušaš!","hero.lede":"Gradijo, medtem ko spiš. Zjutraj te čaka ena kratka skupina: nekaj vprašanj, nekaj reči za preizkus, kak vijoličen diamant. Klik, sprejem in nazaj h kavi.","dl.windows":"Aplikacija za Windows","dl.browser":"Zaženi v brskalniku","dl.messenger":"📱 Messenger za tvoj telefon","dl.soon":"Kmalu","dl.notify":"🔔 Sporoči mi, ko se odpre","dl.notifySmall":"Alfa ali beta","hero.secondary":"Agilno, le da ekipa nikoli ne potrebuje jutranje kave na stand-upu. (Stand-upe imajo vseeno.)","pitch.h2":"AI-gile v toliko besedah, kolikor jih želiš","pitch.lede":"Izberi dolžino, od ene besede do 144. Vsaka dolžina je svoj opis, napisan prav zanjo. Povleci drsnik ali uporabi puščice.","pitch.rangeLabel":"Dolžina v besedah","pitch.dice":"🎲 druga različica","pitch.words.one":"{n} beseda","pitch.words.other":"{n} besed","pitch.letters.one":"{n} črka","pitch.letters.other":"{n} črk","pitch.chars.one":"{n} znak","pitch.chars.other":"{n} znakov","count.line.html.one":"{n} kartica je zdaj na tabli","count.line.html.other":"{n} kartic je zdaj na tabli","people.humans.html.one":"👥 {n} človek","people.humans.html.other":"👥 {n} ljudi","people.agents.html.one":"🤖 {n} agent","people.agents.html.other":"🤖 {n} agentov","people.working.html.one":"⚡ {n} prav zdaj na delu","people.working.html.other":"⚡ {n} prav zdaj na delu","pre.title":"AI-gile: nekaj nastaja","pre.description":"Tukaj nekaj nastaja: tabla, na kateri AI ekipe gradijo, kar si želiš, in te sproti učijo. Za zdaj zaprta pred-alfa s prijatelji.","pre.h1":"Tukaj nekaj nastaja. 🤫","pre.line":"Tabla, na kateri AI ekipe gradijo, kar si želiš, in te sproti učijo. Za zdaj zaprta pred-alfa s prijatelji.","pre.btn":"🔔 Sporoči mi, ko se odpre","pre.peek":"Za steklom: prava tabla, v živo. Vsaka kartica je barvna črta.","pre.peekFake":"Za steklom: tako je videti tabla pri delu.","features.aria":"Kaj počne","f.pile.h":"Ena skupina zate","f.pile.html":"<b>Zate</b> zbere vse, kar čaka nate, čez vse projekte: vprašanja, reči za preizkus, naloge, ki jih zmore le človek. Tvoja vrsta pove, kaj je na vrsti in koliko časa bo trajalo.","f.sleep.h":"Ekipe, ki delajo, medtem ko spiš","f.sleep.p":"Vsak projekt ima vodjo in ekipo AI agentov. Napiši komentar h kartici in ekipa se zbudi, opravi delo in ti ga vrne s koraki, ki jih zmore tudi utrujen človek.","f.tester.h":"Najprej preveri AI testnik","f.tester.p":"Preden karkoli pride do tebe, testnik v kopiji aplikacije sledi korakom in pokaže, kaj je videl, s posnetkom zaslona. Preleti uspešne in sprejmi z enim klikom.","f.proof.h":"Dokazi, ne obljube","f.proof.p":"Vsaka predaja pokaže, kaj se je spremenilo: datoteke, razlike, posnetke zaslona. Ni treba odpirati vsake aplikacije, da vidiš, ali je končano.","f.chat.h":"Klepet z vodji","f.chat.p":"Stranska vrstica kot na Discordu: ena ikona na projekt, vijolični diamanti za to, kar potrebuje tebe. Vodji pošlji idejo; ta jo spremeni v kartice in načrt z gumbom ✅ Daj.","f.tidy.h":"Sam skrbi za red","f.tidy.p":"Sorodne kartice se združijo, zmedeni naslovi se popravijo, preverjanje žetonov pa drži kodo vitko. Manj stvari za preklapljanje, manj za razmišljanje.","f.private.h":"Tvoje, na tvojem računalniku","f.private.li1":"Tabla teče na tvojem računalniku in odgovarja samo tebi.","f.private.li2":"Zasebna sporočila med ljudmi so šifrirana od konca do konca.","f.private.li3":"Brez računov, brez sledilnikov, brez piškotkov.","f.lang.h":"V tvojem jeziku","f.lang.p":"Več kot 120 jezikov, od nizozemščine, valižanščine in japonščine do piratščine, Yodove govorice in klingonščine, s hitrim preklopom nazaj v angleščino za strokovne izraze.","f.service.h":"Od ideje do prave storitve","f.service.p":"Si z AI zgradil nekaj, kar ljudje zdaj uporabljajo? Označi to kot storitev in tabla ti pomaga, da jo dobro vodiš: preverjanja dosegljivosti, javna stran stanja, incidenti z analizo, spremembe, ki potrebujejo Go, varnostne kopije, preverjene vsak dan. Pomoč te sproti nauči vsakega koraka.","msgr.h2":"AI-gile Messenger: tvoja ekipa v žepu","msgr.p1":"Pogovarjaj se s svojo AI ekipo, ne da bi odprl tablo. Klepetaj z vodji projektov in prijatelji, si oglej testne korake kartice in nanje odgovori, vse s telefona.","msgr.p2":"Za povezavo skeniraj QR kodo na svoji tabli. Prvič? Prijazen predstavitveni klepet ti vse pokaže.","msgr.when":"Najprej Android, nato spletna različica za telefone in iPhone.","msgr.who":"Tvoj vodja projekta","msgr.b1":"Popravek temnega načina je pripravljen. Želiš testne korake?","msgr.b2":"Ja, prosim!","msgr.b3":"1. Odpri Nastavitve. 2. Izberi Temno. Je videti prav?","tl.aria":"Časovnica od prvega pogovora do načrta","tl.h2":"Od prvega klepeta do tega, kar sledi","tl.lede":"Pravi datumi in ure v tvojem časovnem pasu. Po današnjem dnevu je to načrt, brez obljubljenih datumov.","tl.today":"Danes","tl.planned":"načrtovano","tl.cards.one":"{n} kartica","tl.cards.other":"{n} kartic","join.h2":"Pridruži se","join.lede":"AI-gile gradita bradat čudak z AuDHD in nekaj bitkami za duševno zdravje ter veliko potrpežljivih agentov. Zaenkrat je zasebna, v zaprti alfi s prijatelji. Bi ga rad preizkusil, ko se odpre?","join.btn":"Sporoči zanimanje","join.small":"Pisali ti bomo po e-pošti, nič drugega","footer.tag":"AI-gile. Brez sledilnikov, brez piškotkov, brez kave na stand-upu.","footer.licence":"Poslovna licenca","footer.status":"Stanje","footer.privacy":"Kaj hranimo","footer.thanks":"Klici po zaslugi ChilledChat","form.sending":"Pošiljanje …","form.failed":"Ni uspelo: poskusi znova pozneje.","form.offline":"AI-gile ni dosegljiv: poskusi znova pozneje.","form.keep":"To uporabimo samo, da ti odgovorimo, potem pa izbrišemo. Brez sledilnikov, brez piškotkov.","form.keepLink":"Kaj hranimo","interest.title":"AI-gile: sporoči mi, ko se odpre alfa","interest.description":"Pusti e-naslov in izvedel boš, ko se odpre zaprta alfa ali beta AI-gile.","interest.h1":"🔔 Sporoči mi, ko se odpre","interest.lede":"AI-gile je v zaprti pred-alfi. Pusti e-naslov in napisali ti bomo enkrat, ko bo zate prostor.","interest.email":"Tvoj e-naslov","interest.which":"Kateri preizkus?","interest.alpha":"Zaprta alfa: zgodnja, groba, veliko sprememb","interest.beta":"Beta: bolj stabilna, pozneje","interest.both":"Katera koli, kar pride prej","interest.submit":"Zapiši me na seznam","interest.thanks":"Hvala! Si na seznamu.","licence.title":"AI-gile: poslovna licenca","licence.description":"Uporabljaš AI-gile v podjetju? Zaprosi za brezplačno poslovno licenco.","licence.h1":"📜 Poslovna licenca","licence.lede":"Uporabljaš AI-gile v službi? Povej nam, kdo si in kaj počneš. Če to prinaša kaj dobrega, je licenca brezplačna.","licence.company":"Podjetje","licence.website":"Spletna stran","licence.what":"Kaj počneš","licence.how":"Kako to pomaga svetu","licence.email":"E-naslov","licence.submit":"Zaprosi","licence.thanks":"Hvala! Odgovorili bomo po e-pošti.","status.title":"Stanje AI-gile","status.h1":"Stanje AI-gile","status.quiet":"Vse mirno","status.intro":"Ali AI-gile ta trenutek deluje? Ta stran vsakih 5 minut preveri spletno mesto, deljenje tabel, klice in prenos.","status.up":"Deluje (odgovor v {ms} ms)","status.slow":"Ni odgovora pri zadnjem preverjanju, poskušam znova","status.down":"Ne deluje: ni odgovora pri zadnjih dveh preverjanjih","status.svc.web":"Spletno mesto","status.svc.web.offers":"To mesto: kaj je AI-gile in obrazec za zanimanje","status.svc.boards":"Deljenje tabel","status.svc.boards.offers":"Javne table, sporočila med prijatelji in povabila","status.svc.calls":"Klici","status.svc.calls.offers":"Glas, video in deljenje zaslona v AI-gile","status.svc.download":"Prenos","status.svc.download.offers":"Namestitveni program za Windows in povezave do povabil","status.checking":"Preverjanje …","status.offline":"Storitev stanja trenutno ni dosegljiva (poskušam znova)","status.updated":"posodobljeno {ago}","status.justNow":"pravkar","status.min":"pred {n} min","status.hours":"pred {n} h","status.days":"pred {n} d","privacy.title":"AI-gile: kaj hranimo","privacy.h1":"Kaj hranimo","privacy.lede":"Na kratko: samo to, kar nam pošlješ, in ne dolgo.","privacy.only":"Samo to, kar nam pošlješ: kar vpišeš v obrazec, na primer svoj e-naslov. Nič drugega o tebi.","privacy.sealed":"Zapečateno je, zato ga naš strežnik ne more prebrati: v tvojem brskalniku, preden odide (v starejšem brskalniku takoj, ko prispe). Odpre ga lahko samo naša tabla.","privacy.server":"S strežnika se izbriše takoj, ko prispe na našo tablo. Kar tam po 30 dneh še ostane, se vseeno izbriše.","privacy.board":"Na naši tabli ga hranimo samo, dokler ti ne odgovorimo, nato ga izbrišemo tudi tam.","privacy.none":"Brez sledilnikov, brez piškotkov, brez analitike.","privacy.local":"Tvoj jezik in izbira svetle ali temne teme ostaneta v tvojem brskalniku. Nikoli ne prideta do nas.","privacy.ask":"Želiš, da izgine prej? Odgovori na naše sporočilo in nam to povej.","live.h2":"Oglejte si, kako nastaja, v živo","live.caption":"Vsaka kartica je skrita: vidite obliko dela, ne besed.","live.watching.one":"v živo: gleda {n}","live.watching.other":"v živo: gledata {n}","live.last.now":"Zadnja kartica premaknjena pravkar","live.last.min.one":"Zadnja kartica premaknjena pred {n} minuto","live.last.min.other":"Zadnja kartica premaknjena pred {n} minutami","live.last.hour.one":"Zadnja kartica premaknjena pred {n} uro","live.last.hour.other":"Zadnja kartica premaknjena pred {n} urami","live.last.day.one":"Zadnja kartica premaknjena pred {n} dnevom","live.last.day.other":"Zadnja kartica premaknjena pred {n} dnevi","live.offline":"Tabla v živo si malo oddahne. Poglejte kmalu znova.","live.cols":"Backlog|Na vrsti|V teku|Ekipa preverja|Zate, v testiranje|Za ekipo|Končano","pitch.words.two":"{n} besedi","pitch.words.few":"{n} besede","pitch.letters.two":"{n} črki","pitch.letters.few":"{n} črke","pitch.chars.two":"{n} znaka","pitch.chars.few":"{n} znaki","count.line.html.two":"{n} kartici sta zdaj na tabli","count.line.html.few":"{n} kartice so zdaj na tabli","tl.cards.two":"{n} kartici","tl.cards.few":"{n} kartice","live.last.min.two":"Zadnja kartica premaknjena pred {n} minutama","live.last.min.few":"Zadnja kartica premaknjena pred {n} minutami","live.last.hour.two":"Zadnja kartica premaknjena pred {n} urama","live.last.hour.few":"Zadnja kartica premaknjena pred {n} urami","live.last.day.two":"Zadnja kartica premaknjena pred {n} dnevoma","live.last.day.few":"Zadnja kartica premaknjena pred {n} dnevi"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboti.","Prepuščeno."]},{"n":2,"texts":["Robotski kanban.","Agenti, urejeni.","Ideje, zgrajene."]},{"n":3,"texts":["Kanban za robote.","Ideje postanejo funkcije.","Brezplačen kanban agentov."]},{"n":5,"texts":["Kanban tabla, ki jo vodijo agenti.","Ti pišeš kartice. Agenti gradijo.","Brezplačno, lokalno, preizkušeno, malce noro."]},{"n":8,"texts":["Brezplačna kanban tabla, kjer delajo AI agenti.","Napiši idejo. Agenti jo zgradijo. Ti jo sprejmeš.","Agilnost za enega človeka in veliko potrpežljivih robotov."]},{"n":13,"texts":["Kanban tabla na tvojem računalniku, kjer kartice prevzemajo AI agenti in delajo nanje.","Napiši idejo. Ekipa agentov jo zgradi. Testnik jo preveri. Ti rečeš da.","Brezplačno, brez računov in sledilnikov: tabla, nekaj robotov in ti kot šef."]},{"n":21,"texts":["AI-gile je kanban tabla za delo z AI agenti, ki programirajo. Oni prevzemajo kartice, ti jih preizkušaš in sprejemaš.","Vsak projekt dobi vodjo in ekipo AI agentov. Napiši komentar k poljubni kartici in ekipa se loti dela.","Brezplačna osebna tabla opravil, ki teče na tvojem računalniku. Delavci so roboti. Da reči pa lahko samo ti."]},{"n":34,"texts":["Ideje daš na tablo. Ekipa AI agentov jih spremeni v delujoče funkcije, jih preizkusi in ti jih vrne s koraki za preizkus. Nič ni opravljeno, dokler tega ne rečeš ti.","AI-gile je domača kanban tabla, ki jo je Rich zgradil z veliko pomočjo agentov, ki jih zdaj sama vodi. Je brezplačna, teče na tvojem računalniku in jo deli s prijatelji, ne prodaja.","Predstavljaj si navadno kanban tablo s stolpci od Backlog do Končano, le da kartice prevzemajo AI agenti. Poročajo o napredku, vprašajo, ko obtičijo, in vedno počakajo na tvoje soglasje."]},{"n":55,"texts":["AI-gile je kanban tabla, kjer ekipo sestavljajo AI agenti. Vsak projekt ima vodjo, ki načrtuje delo, in pomočnike, ki ga gradijo. Ko je funkcija pripravljena, jo AI testnik preizkusi in naredi posnetek zaslona, nato pristane na tvoji skupini. Sprejmi jo ali napiši komentar in jo predelajo.","Začelo se je kot način, da si en človek zapomni veliko AI programerskih sej hkrati, nato pa zraslo v pravo tablo. Teče na tvojem računalniku, ne potrebuje računa in nima sledilnikov. Za prijatelje in radovedneže je brezplačna. Je tudi nedokončana, zato računaj na robove in občasno presenečenje.","Tukaj je poštena različica. Ideje moraš še vedno imeti ti, rezultate moraš še vedno preveriti ti. AI-gile naredi vse vmes: drži kartice urejene, zbudi pravega agenta, ko napišeš komentar, natančno pokaže, kaj se je spremenilo, in vse zloži v eno kratko skupino zate, ki jo zmoreš pregledati ob jutranji kavi. Ostalo je še vedno tvoje."]},{"n":89,"texts":["AI-gile je brezplačna kanban tabla, ki jo poganjaš na svojem računalniku. Namesto ljudi ima vsak projekt ekipo AI agentov: vodjo, ki tvoje ideje spremeni v kartice in načrt, in pomočnike, ki kartice prevzemajo po prednosti. Ko je nekaj zgrajeno, AI testnik sledi korakom testa in ti pokaže, kaj je videl. Potem čaka v eni skupini z imenom Zate. Sprejmeš ali napišeš komentar in ekipa poskusi znova. Nič ne pride do Končano brez tebe.","Nekaj reči, ki jih morda ne pričakuješ. Nočna straža polni stolpec Na vrsti, medtem ko spiš, in izbira kartice, ki od tebe ne potrebujejo odgovora. Števec žetonov kaže, koliko so agenti porabili danes in ta teden, Način brez žetonov pa jim ukaže, naj nehajo trošiti. S prijatelji si lahko pišeš, zasebna sporočila pa so šifrirana od konca do konca. Tabla govori približno 120 jezikov, tudi nizozemščino, flamščino, piratščino in klingonščino. Nič od tega ne stane niti centa in nihče ti tega niti ne poskuša prodati.","AI-gile je majhen osebni projekt, ne podjetje. Rich je želel skrbeti za več AI programerskih projektov, ne da bi odpiral vsako aplikacijo, zato je skupaj z agenti zgradil tablo in z njo zgradil še preostanek sebe. Je v zaprti pred-alfi, kar pomeni, da deluje, večinoma, za peščico prijateljev. Nima cenika, glasila ali načrta rasti. Teče na tvojem računalniku, brez računov in brez sledilnikov. Če se ti zdi uporabno, lahko zaprosiš za preizkus, ko se malo bolj odpre."]},{"n":144,"texts":["AI-gile je kanban tabla za enega človeka in veliko AI agentov. Teče na tvojem računalniku in je povsem brezplačna. Dodaš projekte in vsak dobi vodjo in majhno ekipo. S vodjo klepetaš, nekako kot na Discordu, in opišeš idejo; vodja jo spremeni v kartice in načrt ter počaka, da pritisneš Daj. Ekipa kartice obdela po prednosti s preprostim ukaznim vmesnikom, narejenim za jezikovne modele. Preden se karkoli vrne k tebi, AI testnik v kopiji aplikacije sledi korakom in priloži posnetek zaslona. Končano delo pristane na tvoji skupini s spremenjenimi datotekami in razlikami. Sprejmeš ga ali pustiš komentar in ekipa se zbudi ter poskusi znova. Kartico v Končano lahko premakneš samo ti, nihče drug. Brez računov, brez sledilnikov, brez piškotkov, vse na tvojem računalniku.","Dan z AI-gile, približno. Zvečer pustiš nekaj komentarjev: ta gumb je na napačnem mestu, tisti seznam naj bo urejen, ali bi lahko imeli temni način. Greš spat. Agenti preberejo komentarje, naredijo spremembe, jih preizkusijo in ti jih vrnejo. Če stolpec Na vrsti usahne, ga nočna straža napolni iz zaloge s karticami, ki od tebe ne potrebujejo odgovora. Zjutraj je ena kratka skupina: nekaj vprašanj in nekaj reči za preizkus, vsaka s koraki, ki jih zmore tudi zaspan človek, in s posnetkom, da deluje. Preklikaš, sprejmeš dobre in preostale pošlješ nazaj. Števec žetonov pokaže, kaj je vse to porabilo, Način brez žetonov pa je tu za skromnejše tedne. Potem zajtrkuješ, pri čemer ti agenti zaenkrat še ne znajo pomagati.","Najprej to, kaj AI-gile ni. Ni startup, ni naprodaj in nihče ne zbira tvojih podatkov. Je brezplačna tabla, ki teče na tvojem računalniku, brez računov, brez sledilnikov in brez piškotkov. Kaj pa je: eno pregledno mesto, kjer vidiš vse AI programerske projekte hkrati, kjer ekipa agentov dela kartice, ti pa odločaš. Združuje sorodne kartice, popravlja zmedene naslove in pazi, da koda ostane vitka. Govori približno 120 jezikov, od nizozemščine in flamščine do piratščine in klingonščine. Prijatelji si lahko pišejo zasebno in šifrirano. Zgradil jo je Rich z množico potrpežljivih agentov, večinoma s pomočjo same sebe. Je v zaprti pred-alfi, zato je mestoma groba. Če se ti zdi zabavno, lepo vprašaj in morda prideš noter prej."]}],"quips":{"1":"Ena beseda. Drzno. Morda preveč.","3":"Tri besede. Že zdaj bolj poštene od večine strani s produkti.","8":"Osem besed. Še vedno krajše od stand-upa.","21":"Dolžine so mimogrede story pointi. Seveda so.","55":"Petinpetdeset besed. Medtem ko si bral, sta se končali dve kartici.","144":"To je dolga. 233 ne obstaja. Agenti so šli spat."}},"timeline":{"first-idea.name":"Prva ideja","first-idea.line":"Čisto prvi pogovor, še preden je obstajala kakršna koli koda.","first-board.name":"Prva tabla","first-board.line":"Tabla, ki spremlja lastno gradnjo: kartice, stolpci, vleci in spusti, projekti.","team-roles.name":"Ekipa in vloge","team-roles.line":"Profili agentov, predloge ekip, prostori in kdo počne kaj.","install.name":"Namestitev in izdaje","install.line":"Zip, ki ga lahko namesti tudi prijatelj, samodejne posodobitve, kanali in vrnitev nazaj.","usage-saver.name":"Varčevanje s porabo","usage-saver.line":"Izmeri, koliko stanejo zagoni, drži kodo vitko, varuj svojo omejitev.","friends.name":"Prijatelji in deljenje","friends.line":"Zasebna sporočila, premešan relej, povabila, vloge in deljeni projekti.","languages.name":"Jeziki","languages.line":"Vsako besedilo zaslona v jezikovni datoteki, najprej nizozemščina in flamščina.","ai-tester.name":"AI testnik","ai-tester.line":"Testnik najprej preveri vsako predajo in pokaže, kaj je videl.","website.name":"Spletna stran","website.line":"aigile.lol, predstavitev in ta časovnica.","streaming.name":"Klepet in pretakanje","streaming.line":"Discord, Twitch, OBS, način pretakalca, GIF-i in emojiji.","no-ai.name":"Izdaja brez AI","no-ai.line":"Tabla za ljudi, ki programirajo brez AI, in javne table.","night-watch.name":"Nočna straža","night-watch.line":"Stražar in Scrum Master držita ekipe pri delu, medtem ko spiš.","p-more.name":"Vse ostalo","p-more.line":"Manjše ideje, ki še čakajo na vrsto.","p-android.name":"Telefon in Android","p-android.line":"Do table s telefona, nato domača aplikacija za Android.","p-release.name":"Alfa in naprej","p-release.line":"Zaprta alfa, živa stran, nato beta.","p-languages.name":"Več jezikov","p-languages.line":"Več kot sto jezikov in potopitveni način za učence.","p-engines.name":"Več AI motorjev","p-engines.line":"Izberi Claude, Codex ali Gemini za vsakega agenta.","p-pro.name":"Profesionalna praksa","p-pro.line":"Oznake tveganja, vrata združevanja, kartice incidentov in varovalke.","p-self.name":"Skrb zate","p-self.line":"Način utrujenosti, opomniki za skrb zase in 4:20.","p-servers.name":"Strežniki in rast","p-servers.line":"Globalne nastavitve strežnika, vloge in načrtovanje rasti.","p-livestream.name":"Dodatki za pretakanje","p-livestream.line":"Twitch klepet, emojiji po meri in javen živ pogled."},"words":{"button":"📖 Strokovni izrazi","h":"📖 Razložene besede","intro":"Besede, ki jih srečaš v AI-gile, preprosto razložene: kako nekaj zgradiš, varno spreminjaš, ohranjaš delujoče za ljudi, ki to uporabljajo, in delaš kot ekipa z AI.","search":"Poišči besedo …","none":"Nobena beseda se ne ujema.","close":"Zapri","count":{"one":"{count} beseda","other":"{count} besed"},"groups":[{"id":"build","name":"🛠️ Gradnja"},{"id":"change","name":"🔀 Varne spremembe"},{"id":"run","name":"🛎️ Delovanje storitve"},{"id":"team","name":"🤝 Delo v ekipi (in z AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Mapa projekta s kodo in celotno zgodovino commitov, običajno shranjena tudi na GitHubu.","also":["repository","repozitorij"]},{"id":"branch","g":"build","word":"Branch","text":"Ločena veja dela v kodi, da je spremembe mogoče delati, ne da bi se dotaknili glavne različice.","also":["branches","veja","veje"]},{"id":"commit","g":"build","word":"Commit","text":"Shranjen posnetek kode s kratkim zapiskom o spremembah. Na vsakega se lahko kadar koli vrneš.","also":["commits","commiti"]},{"id":"push","g":"build","word":"Push","text":"Pošiljanje shranjenih posnetkov (commitov) iz tega računalnika na GitHub, da so na varnem in na voljo drugim."},{"id":"merge","g":"build","word":"Merge","text":"Združitev sprememb veje nazaj v glavno različico."},{"id":"pr","g":"build","word":"Pull request","text":"Prošnja, da se spremembe veje preverijo in združijo v glavno različico.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Urejanje kode brez spremembe njenega delovanja: manjše datoteke, jasnejša imena, manj ponavljanja."},{"id":"bug","g":"build","word":"Bug","text":"Nekaj, kar ne deluje tako, kot bi moralo.","also":["bugs","bugi","napaka","napake"]},{"id":"test","g":"build","word":"Test","text":"Preizkus dokončanega dela, da preveriš, ali dela, kar je bilo zahtevano, preden ga sprejmeš.","also":["tests","testi"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Kratica za quality assurance, zagotavljanje kakovosti: samodejna preverjanja, ki tečejo, preden kar koli gre v živo. Ko je QA rdeč, je nekaj padlo in v živo ne gre, dokler tega ne popravijo.","also":["preverjanje kakovosti","zagotavljanje kakovosti"]},{"id":"deploy","g":"change","word":"Deploy","text":"Objava nove različice v živo, na primer na strežnik, kjer jo ljudje uporabljajo."},{"id":"release","g":"change","word":"Izdaja","text":"Poimenovan paket dokončanega dela, ki gre v živo skupaj, s kratkimi opombami, kaj se je spremenilo. 🚀 Izdaje napišejo opombe iz opravljenih kartic.","also":["izdaje","release"]},{"id":"rollback","g":"change","word":"Povrnitev","text":"Vrnitev na zadnjo različico, ki je delovala, ko nova povzroča težave. V AI-gile iz tega nastane kontrolni seznam korakov za razveljavitev, zapisanih pri vsaki spremembi.","also":["rollback","povrni","povrnjeno"]},{"id":"live","g":"change","word":"V živo","text":"Prava različica, ki jo ljudje uporabljajo, v nasprotju s kopijo za preizkušanje. Razvijalci ji rečejo tudi produkcija.","also":["produkcija","live"],"noTip":1},{"id":"change","g":"change","word":"Sprememba","text":"Načrtovana sprememba nečesa, na kar se ljudje zanašajo, najprej zapisana: kaj, zakaj, tveganje, kdaj in kako jo razveljaviš. Začni jo z 🔀 Vloži spremembo.","also":["spremembe","zahtevek za spremembo","zahtevki za spremembo"],"noTip":1},{"id":"risk","g":"change","word":"Tveganje","text":"Nekaj, kar bi lahko šlo narobe, ocenjeno po tem, kako verjetno je in kako hudo bi bilo. ⚠️ Tveganja jih hranijo na enem seznamu, najvišja ocena prva, vsako z datumom, ko ga spet pogledaš.","also":["tveganja","register tveganj"]},{"id":"chgwin","g":"change","word":"Okno sprememb","text":"Časi, ko lahko spremembe gredo v živo, na primer miren torkov večer. Zunaj okna kartice spremembe ni mogoče zaključiti, razen če gre za nujen primer.","also":["okna sprememb","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Hitro glasovanje tik preden gre sprememba v živo: vsak, ki jo mora odobriti, reče Go ali No go. Izvede se le, ko se strinjajo.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Odobritev","text":"Čakanje na da, preden se delo začne. Kartica, ki jo odpre prijatelj, ali sprememba čaka v ✅ Odobritvah, dokler je ne odobriš ali zavrneš.","also":["odobritve","odobri"]},{"id":"quiettime","g":"change","word":"Čas tišine","text":"Obdobje, kot je prenos v živo, demo ali noč, ko nič ne gre v živo. Ekipe še naprej delajo in testirajo, objava pa počaka, da se konča. Drugje temu rečejo zamrznitev sprememb.","also":["časi tišine","zamrznitev sprememb","change freeze"]},{"id":"service","g":"run","word":"Storitev","text":"Nekaj, kar si zgradil in na kar se ljudje zanašajo, na primer spletna stran ali aplikacija, za kar nekdo skrbi, da deluje. Označi »Ta projekt je storitev« in napiši, kaj ponuja, kdo jo uporablja in kdo je dežuren.","also":["storitve","servis"]},{"id":"uptime","g":"run","word":"Preverjanje dosegljivosti","text":"Samodejno preverjanje vsakih nekaj minut, ali tvoja storitev še odgovarja. Če večkrat zapored ne uspe, AI-gile sam odpre kartico incidenta.","also":["dosegljivost","uptime","preverjanja dosegljivosti"]},{"id":"statuspage","g":"run","word":"Stran stanja","text":"Javna stran, ki pokaže, ali storitev deluje (zeleno, oranžno ali rdeče), z zadnjo novico, da lahko uporabniki pogledajo sami, namesto da sprašujejo.","also":["strani stanja","statusna stran","status page"]},{"id":"incident","g":"run","word":"Incident","text":"Nekaj, kar je pravkar pokvarjeno za ljudi, ki to uporabljajo, na primer ko spletna stran ne deluje. Kartica 🔥 incidenta preskoči vrsto: najprej mora spet delovati.","also":["incidenti","izpad"]},{"id":"major","g":"run","word":"Velik incident","text":"Velik incident: prizadetih je veliko ljudi ali pa sta ogrožena denar ali podatki. En gumb postavi vse ekipe nanj (roj), zbudi dežurnega in vsakih 30 minut zahteva novico o stanju.","also":["veliki incidenti","major incident"]},{"id":"oncall","g":"run","word":"Dežurstvo","text":"Biti tisti, ki se odzove, ko se kaj pokvari, tudi ponoči. Vsaka storitev ima dežurnega člana ekipe, ki ga ob njenih incidentih zbudijo prvega.","also":["dežuren","dežurni","on call","on-call"]},{"id":"replyby","g":"run","word":"Rok za odgovor","text":"Kako dolgo lahko kartica čaka na prvi odgovor, na primer eno uro pri incidentu. Potem dobi rdečo uro, da se nič tiho ne pozabi. Pravijo mu tudi ciljni odzivni čas.","also":["roki za odgovor","ciljni odzivni čas"]},{"id":"postmortem","g":"run","word":"Analiza incidenta","text":"Kratek pogled nazaj po incidentu: kaj se je zgodilo, kaj je pomagalo in kaj spremeniti, brez obtoževanja kogar koli. Incidenta brez nje ni mogoče zapreti. Pogosto ji rečejo tudi post-mortem.","also":["analize incidentov","post-mortem","postmortem"]},{"id":"problem","g":"run","word":"Težava","text":"Skriti vzrok za enim ali več incidenti. Kartica 🧩 težave združi incidente, ki se vračajo, da se vzrok najde in odpravi za vedno.","also":["težave","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Osnovni vzrok","text":"Pravi razlog, zakaj se je nekaj pokvarilo, ne le to, kar si videl, da gre narobe. Odpravi osnovni vzrok in incident se neha vračati.","also":["osnovni vzroki","root cause"]},{"id":"workaround","g":"run","word":"Začasna rešitev","text":"Način, kako stvari ohraniti delujoče, dokler prava rešitev ni pripravljena, na primer ponovni zagon, ko se kaj zatakne. Zapiše se na kartico težave, da je nihče ne rabi spet iskati.","also":["začasne rešitve","workaround","obvod"]},{"id":"knownerror","g":"run","word":"Znana napaka","text":"Težava, katere vzrok je jasen in ima začasno rešitev, a še ni odpravljena. 🧩 Znane napake jih naštejejo, da vsi uporabijo začasno rešitev, namesto da spet kopljejo.","also":["znane napake","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Navodila korak za korakom za odpravo znane vrste težave, da se vsakič naredi enako in hitro. Po velikem incidentu ti ga ekipa lahko predlaga v potrditev.","also":["runbooki","postopek","priročnik"]},{"id":"backup","g":"run","word":"Varnostna kopija","text":"Shranjena kopija tvojih podatkov od prej, na katero se lahko zaneseš, če se kaj izgubi ali poškoduje. AI-gile vsak dan naredi varnostno kopijo tvojih tabel.","also":["varnostne kopije","backup","varnostno kopiranje"]},{"id":"restore","g":"run","word":"Obnovitev","text":"Vračanje podatkov iz varnostne kopije. Varnostna kopija zares šteje šele, ko veš, da jo lahko obnoviš, zato se jo splača kdaj pa kdaj preizkusiti.","also":["obnovi","obnovljeno","restore"]},{"id":"backlog","g":"team","word":"Backlog","text":"Ideje in delo, ki še nista načrtovana. Nič od tega se ne dela, dokler se ne premakne v stolpec Na vrsti."},{"id":"sprint","g":"team","word":"Sprint","text":"Kratko obdobje dela (pogosto teden ali dva) z dogovorjenim naborom kartic, ki jih je treba dokončati.","also":["sprints","sprinti","sprint"]},{"id":"standup","g":"team","word":"Stand-up","text":"Hiter pregled: kaj je kdo naredil, kaj dela naprej in kaj ga ovira.","also":["standup","stand-ups","stand-upi"]},{"id":"kanban","g":"team","word":"Kanban","text":"Tabla s stolpci (Na vrsti, V teku, Končano), kjer se kartice med delom premikajo od leve proti desni."},{"id":"wip","g":"team","word":"WIP limit","text":"Delo v teku: največ kartic, ki jih sme imeti stolpec, da ekipa stvari dokonča, preden začne nove.","also":["WIP","omejitev dela v teku"]},{"id":"dod","g":"team","word":"Definicija Opravljeno","text":"Kratek kontrolni seznam ekipe, kaj pomeni »dokončano«, na primer testirano in razloženo, preden ti kartico predajo. Njen dvojček, Definicija Pripravljeno, pove, kdaj je kartica dovolj jasna za začetek.","also":["Definition of Done","Definicija Pripravljeno","Definition of Ready"]},{"id":"testpile","g":"team","word":"Kup testov","text":"Dokončane kartice, ki čakajo, da jih preizkusiš, ena za drugo. Eno sprejmi ali jo vrni z opombo in pride naslednja.","also":["kupi testov"]},{"id":"retro","g":"team","word":"Retro","text":"Pogled nazaj na to, kako ekipa dela, da se dogovori o eni stvari, ki jo bo delala bolje. V AI-gile retro predlaga spremembo načina dela ekipe, ti pa rečeš Go ali Še ne.","also":["retrospektiva","retrospektive"]},{"id":"peerreview","g":"team","word":"Vzajemni pregled","text":"Drugi par oči: druga AI preveri delo vsake kartice, preden pride do tebe, da zdrsne skozi manj napak.","also":["peer review","pregled kode","code review"]},{"id":"swarm","g":"team","word":"Roj","text":"Vsi na krov: vsaka ekipa odloži drugo delo in pomaga pri enem nujnem projektu, dokler ni urejeno. Drugi projekti medtem počakajo.","also":["swarm","swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"Tisti, ki skrbi, da delo teče: opazi obtičale kartice, spodbudi ekipe in te opomni, kaj čaka. V AI-gile to v vseh projektih počne Lead Scrum Master.","also":["Lead Scrum Master","glavni Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"AI, ki samostojno dela na nalogi: bere kodo, spreminja, izvaja preverjanja in poroča.","also":["agents","agenti"]},{"id":"token","g":"team","word":"Token","text":"Enota, v kateri se šteje poraba AI: približno nekaj črk prebranega ali napisanega besedila. Manj žetonov pomeni, da ti ostane več paketa.","also":["tokens","žeton","žetoni"]},{"id":"hook","g":"team","word":"Hook","text":"Majhen ukaz, ki se sam zažene ob določenem trenutku, npr. ko se začne seja AI, da ekipa sliši tvoje komentarje.","also":["hooks","kljuka","kljuke"]}]}};
